import { usersDBPool } from '../../database/postgres.database';

type Column = {key: string; label: string; format?: string};
type Metric = Column & {sql: string};
type Spec = {id: string; title: string; group: string; description: string; basis: string; notes: string[]; dates: 'period'|'asof'|'none'; scope: boolean; columns: Column[]; metrics: Metric[]; sql: string; sort: string; chart?: {label: string; value: string; kind?: string}};
const col = (key: string, label: string, format = 'text'): Column => ({key,label,format});
const metric = (key: string, label: string, sql: string, format = 'number'): Metric => ({key,label,sql,format});
const money = (key: string, label: string) => col(key,label,'money');
const n = (sql: string) => `CASE WHEN (${sql}) ~ '^-?[0-9]+([.][0-9]+)?$' THEN (${sql})::numeric ELSE NULL END`;
const fulfilled = `status IN ('ORDER_DELIVERED','COMPLETED')`;
const cancelled = `status IN ('ORDER_CANCELLED','CANCELLED')`;
const partial = `status = 'ORDER_PARTIALLY_DELIVERED'`;
const scope = (outlet: string, station: string) => `($3::int IS NULL OR ${outlet}=$3) AND ($4::text IS NULL OR UPPER(${station})=UPPER($4))`;
const period = (date: string) => `($1::date IS NULL OR ${date} >= $1::date) AND ($2::date IS NULL OR ${date} < $2::date + INTERVAL '1 day')`;
const asof = `COALESCE($2::date,(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date)`;
const outlets = `outlets AS MATERIALIZED (
 SELECT DISTINCT ON (outlet_id) outlet_id,outlet_name,station_code,vendor_id,status,verified,fssai,fssai_valid,phone,email,wallet_threshold,created_at
 FROM restraunts.restraunt_master WHERE outlet_id IS NOT NULL
 ORDER BY outlet_id,(status=1) DESC NULLS LAST,verified DESC NULLS LAST,id ASC)`;
const orderBase = `${outlets}, order_facts AS MATERIALIZED (
 SELECT o.oid::text AS order_id,o.outlet_id,COALESCE(r.outlet_name,'Unmapped outlet') AS outlet_name,
 COALESCE(NULLIF(o.station_code,''),r.station_code,'Unrecorded') AS station,
 UPPER(COALESCE(o.status,'UNKNOWN')) AS status,
 CASE WHEN UPPER(o.mode) IN ('PRE_PAID','PREPAID') THEN 'PREPAID' WHEN UPPER(o.mode)='CASH_ON_DELIVERY' THEN 'COD' ELSE COALESCE(o.mode,'Unrecorded') END AS payment_mode,
 COALESCE(NULLIF(o.booked_from,''),'Unrecorded') AS channel,
 public.safe_parse_created_at(o.created_at) AS booked_at,public.safe_parse_created_at(o.delivery_date) AS delivery_at,
 o.menu_items,o.customer_info,o.delivery_details,COALESCE(o.reason,'') AS reason,
 public.safe_parse_created_at(o.updated_at) AS updated_at,
 o.discount_amount,o.irctc_discount,o.vendor_discount,o.tax AS recorded_tax,
 COALESCE(NULLIF(o.delivery_details #>> '{deliveryDetails,trainNo}',''),'Unrecorded') AS train_no,
 COALESCE(NULLIF(o.delivery_details #>> '{deliveryDetails,trainName}',''),'Unrecorded') AS train_name,
 v.item_value,v.units,v.missing_prices,v.item_count,
 COALESCE(NULLIF(regexp_replace(COALESCE(o.customer_info #>> '{customerDetails,mobile}',o.customer_info->>'mobile',''),'[^0-9]','','g'),''),
 NULLIF(LOWER(COALESCE(o.customer_info #>> '{customerDetails,email}',o.customer_info->>'email')),''),
 NULLIF(COALESCE(o.customer_info #>> '{customerDetails,customerId}',o.customer_info->>'customerId'),'')) AS customer_key
 FROM orders.orders_master o LEFT JOIN outlets r ON r.outlet_id=o.outlet_id
 LEFT JOIN LATERAL (
   SELECT COALESCE(SUM(${n("i->>'SellingPrice'")}*COALESCE(${n("i->>'quantity'")},1)),0) AS item_value,
   COALESCE(SUM(COALESCE(${n("i->>'quantity'")},1)),0) AS units,
   COUNT(*) FILTER(WHERE ${n("i->>'SellingPrice'")} IS NULL)::int AS missing_prices,COUNT(*)::int AS item_count
   FROM jsonb_array_elements(CASE WHEN jsonb_typeof(o.menu_items)='array' THEN o.menu_items WHEN jsonb_typeof(o.menu_items->'items')='array' THEN o.menu_items->'items' ELSE '[]'::jsonb END) i
 ) v ON TRUE), orders AS MATERIALIZED (
 SELECT * FROM order_facts WHERE ${period('booked_at')} AND ${scope('outlet_id','station')})`;
const orderNotes = ['Orders are grouped by booking date in Asia/Kolkata. Mixed legacy dates use the system’s safe date parser.',
 'Item value is the saved SellingPrice × quantity on the order. It is not bank receipts or net profit. Recorded discounts and tax are shown separately, without assuming whether item prices already include them.',
 'Delivered value includes ORDER_DELIVERED and completed only. Partial deliveries, cancellations, undelivered and open orders are excluded from delivered value.'];
const performanceColumns = [col('orders','Orders','number'),col('delivered','Delivered','number'),col('partial','Partial','number'),col('cancelled','Cancelled','number'),col('undelivered','Undelivered','number'),col('delivery_rate','Delivered %','percent'),money('booked_value','Booked item value'),money('delivered_value','Delivered item value')];
const performanceSql = `COUNT(*)::int AS orders,COUNT(*) FILTER(WHERE ${fulfilled})::int AS delivered,COUNT(*) FILTER(WHERE ${partial})::int AS partial,
 COUNT(*) FILTER(WHERE ${cancelled})::int AS cancelled,COUNT(*) FILTER(WHERE status='ORDER_UNDELIVERED')::int AS undelivered,
 ROUND(100.0*COUNT(*) FILTER(WHERE ${fulfilled})/NULLIF(COUNT(*),0),2) AS delivery_rate,
 COALESCE(SUM(item_value),0) AS booked_value,COALESCE(SUM(item_value) FILTER(WHERE ${fulfilled}),0) AS delivered_value`;
const performanceMetrics = [metric('orders','Orders','COALESCE(SUM(orders),0)'),metric('delivered','Delivered','COALESCE(SUM(delivered),0)'),metric('delivered_value','Delivered item value','COALESCE(SUM(delivered_value),0)','money'),metric('cancelled','Cancelled','COALESCE(SUM(cancelled),0)')];
const specs: Spec[] = [];
function add(s: Spec) {specs.push(s);}
for (const [id,title,group,key,label,extra] of [
 ['daily-sales','Daily business summary','Operations',`booked_at::date::text`,'Day',''],
 ['outlet-performance','Outlet performance','Operations','outlet_id','Outlet ID',',outlet_name,station'],
 ['station-performance','Station performance','Operations','station','Station',''],
 ['train-performance','Train demand & delivery','Operations','train_no','Train number',',train_name'],
 ['payment-mix','Payment mode performance','Sales','payment_mode','Payment mode',''],
 ['channel-performance','Booking channel performance','Sales','channel','Booking channel','']
]) {
 const alias = id==='daily-sales'?'day':key;
 const extras: Column[] = extra.includes('outlet_name')?[col('outlet_name','Outlet'),col('station','Station')]:extra.includes('train_name')?[col('train_name','Train')]:[];
 add({id,title,group,description:'Compare order volume, delivery outcomes and saved order values.',basis:'Order booking date (IST)',notes:orderNotes,dates:'period',scope:true,
 columns:[col(alias,label,id==='daily-sales'?'date':'text'),...extras,...performanceColumns],metrics:performanceMetrics,
 sql:`WITH ${orderBase} SELECT ${key} AS ${alias}${extra},${performanceSql} FROM orders GROUP BY ${key}${extra}`,
 sort:id==='daily-sales'?'day DESC':`orders DESC,${alias} ASC`,chart:{label:id==='outlet-performance'?'outlet_name':alias,value:'delivered_value',kind:id==='daily-sales'?'trend':'bars'}});
}
add({id:'order-register',title:'Order register',group:'Operations',description:'An exportable record of every order and its saved prices.',basis:'Order booking date (IST)',notes:orderNotes,dates:'period',scope:true,
 columns:[col('order_id','Order ID'),col('booked_at','Booked at','datetime'),col('delivery_at','Delivery date','datetime'),col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('train_no','Train'),col('status','Status'),col('payment_mode','Payment mode'),col('units','Units','number'),money('item_value','Saved item value'),money('recorded_tax','Recorded tax'),money('discount_amount','Recorded discount'),col('missing_prices','Items missing prices','number')],
 metrics:[metric('orders','Orders','COUNT(*)'),metric('item_value','Booked item value','COALESCE(SUM(item_value),0)','money'),metric('incomplete','Orders with incomplete items',`COUNT(*) FILTER(WHERE missing_prices>0 OR item_count=0)`),metric('discount','Recorded discounts','COALESCE(SUM(discount_amount),0)','money')],
 sql:`WITH ${orderBase} SELECT order_id,to_char(booked_at,'YYYY-MM-DD HH24:MI') AS booked_at,to_char(delivery_at,'YYYY-MM-DD HH24:MI') AS delivery_at,outlet_id,outlet_name,station,train_no,status,payment_mode,units,item_value,recorded_tax,discount_amount,missing_prices,item_count FROM orders`,sort:'booked_at DESC,order_id DESC'});
add({id:'order-exceptions',title:'Delivery & cancellation exceptions',group:'Operations',description:'Cancelled, undelivered, partial and past-due open orders needing review.',basis:'Order booking date (IST); past-due evaluated now',notes:[...orderNotes,'Past-due means an open order with a saved delivery date earlier than now; it does not measure delivery lateness because no actual delivered timestamp is stored.'],dates:'period',scope:true,
 columns:[col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),col('status','Status'),col('delivery_at','Scheduled delivery','datetime'),col('exception','Review reason'),money('item_value','Saved item value'),col('reason','Saved reason')],
 metrics:[metric('exceptions','Exceptions','COUNT(*)'),metric('cancelled','Cancelled',`COUNT(*) FILTER(WHERE status IN ('ORDER_CANCELLED','CANCELLED'))`),metric('partial','Partial delivery',`COUNT(*) FILTER(WHERE status='ORDER_PARTIALLY_DELIVERED')`),metric('value','Affected item value','COALESCE(SUM(item_value),0)','money')],
 sql:`WITH ${orderBase} SELECT order_id,outlet_name,station,status,to_char(delivery_at,'YYYY-MM-DD HH24:MI') AS delivery_at,item_value,reason,
 CASE WHEN ${cancelled} THEN 'Cancelled' WHEN ${partial} THEN 'Partially delivered' WHEN status='ORDER_UNDELIVERED' THEN 'Undelivered' ELSE 'Open past scheduled delivery' END AS exception
 FROM orders WHERE ${cancelled} OR ${partial} OR status='ORDER_UNDELIVERED' OR (status IN ('ORDER_PLACED','ORDER_PENDING','ORDER_CONFIRMED','ORDER_PREPARING','ORDER_PREPARED','ORDER_OUT_FOR_DELIVERY') AND delivery_at < CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')`,sort:'delivery_at DESC NULLS LAST,order_id DESC'});
add({id:'order-sla',title:'Order SLA timers & ageing',group:'Operations',description:'Prioritise open orders by scheduled delivery risk and measure recorded order ageing.',basis:'Saved booking, delivery and update timestamps in Asia/Kolkata',notes:[...orderNotes,'Open timers count down to the saved delivery date and become overdue after it. Closed cycle time uses the saved updated_at value because the database does not have a separate verified delivered_at timestamp. This is an operational SLA view, not a provider-confirmed delivery timestamp.'],dates:'period',scope:true,
 columns:[col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),col('train_no','Train'),col('status','Status'),col('delivery_at','Scheduled delivery','datetime'),col('sla_state','SLA state'),col('minutes_to_delivery','Minutes to delivery','number'),col('age_minutes','Age / cycle minutes','number'),money('item_value','Saved item value')],
 metrics:[metric('orders','Orders','COUNT(*)'),metric('open','Open timers',`COUNT(*) FILTER(WHERE status NOT IN ('ORDER_DELIVERED','COMPLETED','ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED'))`),metric('overdue','Overdue open orders',`COUNT(*) FILTER(WHERE sla_state='Overdue')`),metric('delivered','Delivered',`COUNT(*) FILTER(WHERE ${fulfilled})`)],
 sql:`WITH ${orderBase} SELECT order_id,outlet_name,station,train_no,status,to_char(delivery_at,'YYYY-MM-DD HH24:MI') AS delivery_at,
 CASE WHEN ${fulfilled} THEN 'Delivered' WHEN ${cancelled} OR status='ORDER_UNDELIVERED' THEN 'Closed' WHEN delivery_at IS NULL THEN 'No delivery time' WHEN delivery_at < CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata' THEN 'Overdue' WHEN delivery_at <= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')+INTERVAL '60 minutes' THEN 'Due within 60 minutes' ELSE 'On track' END AS sla_state,
 CASE WHEN status NOT IN ('ORDER_DELIVERED','COMPLETED','ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED') AND delivery_at IS NOT NULL THEN ROUND(EXTRACT(EPOCH FROM (delivery_at-(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')))/60)::int END AS minutes_to_delivery,
 CASE WHEN ${fulfilled} AND updated_at IS NOT NULL AND booked_at IS NOT NULL THEN ROUND(EXTRACT(EPOCH FROM (updated_at-booked_at))/60)::int WHEN status NOT IN ('ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED') AND booked_at IS NOT NULL THEN ROUND(EXTRACT(EPOCH FROM ((CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')-booked_at))/60)::int END AS age_minutes,item_value
 FROM orders`,sort:'sla_state ASC,minutes_to_delivery ASC NULLS LAST,order_id DESC'});
add({id:'train-delay-risk',title:'Train delivery risk monitor',group:'Operations',description:'Monitor train orders whose saved delivery window is at risk.',basis:'Saved delivery date and latest order state; no live railway position feed is configured',notes:[...orderNotes,'This identifies order delivery risk from the saved schedule. It does not claim a live train delay or railway status. Add a verified railway feed before treating it as a train-location alert.'],dates:'period',scope:true,
 columns:[col('order_id','Order ID'),col('train_no','Train number'),col('train_name','Train'),col('station','Delivery station'),col('outlet_name','Outlet'),col('status','Order status'),col('delivery_at','Scheduled delivery','datetime'),col('risk','Risk'),col('minutes_to_delivery','Minutes to delivery','number'),money('item_value','Saved item value')],
 metrics:[metric('orders','Train orders','COUNT(*)'),metric('risk','At-risk orders',`COUNT(*) FILTER(WHERE risk IN ('Overdue','Due within 60 minutes'))`),metric('open','Open train orders',`COUNT(*) FILTER(WHERE status NOT IN ('ORDER_DELIVERED','COMPLETED','ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED'))`)],
 sql:`WITH ${orderBase} SELECT order_id,train_no,train_name,station,outlet_name,status,to_char(delivery_at,'YYYY-MM-DD HH24:MI') AS delivery_at,
 CASE WHEN status IN ('ORDER_DELIVERED','COMPLETED') THEN 'Delivered' WHEN status IN ('ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED') THEN 'Closed' WHEN delivery_at IS NULL THEN 'Schedule missing' WHEN delivery_at < CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata' THEN 'Overdue' WHEN delivery_at <= (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')+INTERVAL '60 minutes' THEN 'Due within 60 minutes' ELSE 'On track' END AS risk,
 CASE WHEN status NOT IN ('ORDER_DELIVERED','COMPLETED','ORDER_CANCELLED','CANCELLED','ORDER_UNDELIVERED') AND delivery_at IS NOT NULL THEN ROUND(EXTRACT(EPOCH FROM (delivery_at-(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')))/60)::int END AS minutes_to_delivery,item_value FROM orders WHERE train_no<>'Unrecorded'`,sort:'risk ASC,minutes_to_delivery ASC NULLS LAST,order_id DESC'});
add({id:'item-sales',title:'Item sales & historical cost coverage',group:'Sales',description:'See what sells, quantities and whether historical vendor costs were saved.',basis:'Booking date of delivered orders (IST)',notes:[...orderNotes,'Only saved order-line VendorPrice is used for historical cost. Today’s menu costs are never substituted. Covered contribution is item value minus saved cost on lines with both prices; it is not a full margin or profit.'],dates:'period',scope:true,
 columns:[col('item_id','Saved item ID'),col('item_name','Item'),col('order_count','Delivered orders','number'),col('units','Units','number'),money('item_value','Delivered item value'),col('cost_missing_units','Units without historical cost','number'),money('covered_cost','Cost on covered lines'),money('covered_contribution','Contribution on covered lines')],
 metrics:[metric('items','Distinct items','COUNT(*)'),metric('units','Units sold','COALESCE(SUM(units),0)'),metric('value','Delivered item value','COALESCE(SUM(item_value),0)','money'),metric('missing','Units without saved cost','COALESCE(SUM(cost_missing_units),0)')],
 sql:`WITH ${orderBase}, lines AS (SELECT order_id,COALESCE(i->>'item_id','Unrecorded') AS item_id,COALESCE(i->>'name','Unnamed item') AS item_name,${n("i->>'SellingPrice'")} AS price,${n("i->>'VendorPrice'")} AS cost,COALESCE(${n("i->>'quantity'")},1) AS qty FROM orders CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(menu_items)='array' THEN menu_items WHEN jsonb_typeof(menu_items->'items')='array' THEN menu_items->'items' ELSE '[]'::jsonb END) i WHERE ${fulfilled})
 SELECT item_id,item_name,COUNT(DISTINCT order_id)::int AS order_count,SUM(qty) AS units,SUM(price*qty) AS item_value,COALESCE(SUM(qty) FILTER(WHERE cost IS NULL),0) AS cost_missing_units,SUM(cost*qty) FILTER(WHERE price IS NOT NULL) AS covered_cost,SUM((price-cost)*qty) AS covered_contribution FROM lines GROUP BY item_id,item_name`,sort:'item_value DESC NULLS LAST,item_id ASC',chart:{label:'item_name',value:'item_value'}});
add({id:'profitability',title:'Recorded profitability & contribution',group:'Finance',description:'Calculate recorded sales contribution from historical order-line prices and vendor costs.',basis:'Delivered order lines with saved SellingPrice and VendorPrice',notes:[...orderNotes,'This is the most complete profitability view available from the current database. Contribution is SellingPrice minus the saved VendorPrice multiplied by quantity. It excludes unrecorded labour, delivery, payment fees, refunds, overhead and tax treatment; missing costs are shown separately and never estimated.'],dates:'period',scope:true,
 columns:[col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('orders','Delivered orders','number'),col('units','Delivered units','number'),money('sales','Recorded sales'),money('known_cost','Known vendor cost'),money('contribution','Recorded contribution'),col('margin_pct','Contribution %','percent'),col('missing_cost_units','Units missing cost','number'),col('coverage_pct','Cost coverage %','percent')],
 metrics:[metric('outlets','Outlets','COUNT(*)'),metric('orders','Delivered orders','COALESCE(SUM(orders),0)'),metric('sales','Recorded sales','COALESCE(SUM(sales),0)','money'),metric('contribution','Recorded contribution','COALESCE(SUM(contribution),0)','money'),metric('missing','Units missing cost','COALESCE(SUM(missing_cost_units),0)')],
 sql:`WITH ${orderBase}, lines AS (
 SELECT order_id,outlet_id,outlet_name,station,COALESCE(${n("i->>'SellingPrice'")},0) AS price,${n("i->>'VendorPrice'")} AS cost,COALESCE(${n("i->>'quantity'")},1) AS qty
 FROM orders CROSS JOIN LATERAL jsonb_array_elements(CASE WHEN jsonb_typeof(menu_items)='array' THEN menu_items WHEN jsonb_typeof(menu_items->'items')='array' THEN menu_items->'items' ELSE '[]'::jsonb END) i WHERE ${fulfilled})
 SELECT outlet_id,MAX(outlet_name) AS outlet_name,MAX(station) AS station,COUNT(DISTINCT order_id)::int AS orders,SUM(qty) AS units,SUM(price*qty) AS sales,SUM(cost*qty) FILTER(WHERE cost IS NOT NULL) AS known_cost,SUM((price-cost)*qty) FILTER(WHERE cost IS NOT NULL) AS contribution,ROUND(100*SUM((price-cost)*qty) FILTER(WHERE cost IS NOT NULL)/NULLIF(SUM(price*qty) FILTER(WHERE cost IS NOT NULL),0),2) AS margin_pct,COALESCE(SUM(qty) FILTER(WHERE cost IS NULL),0) AS missing_cost_units,ROUND(100*SUM(qty) FILTER(WHERE cost IS NOT NULL)/NULLIF(SUM(qty),0),2) AS coverage_pct FROM lines GROUP BY outlet_id`,sort:'contribution DESC NULLS LAST,outlet_id ASC',chart:{label:'outlet_name',value:'contribution'}});
add({id:'customers',title:'Customer frequency & value',group:'Sales',description:'Identify repeat passengers and their delivered order value.',basis:'Order booking date (IST)',notes:[...orderNotes,'Customers are grouped by normalized phone, then email, then saved customer ID. Repeat means at least two orders in the selected period, not lifetime retention. Orders without an identifier are excluded.'],dates:'period',scope:true,
 columns:[col('customer_key','Contact identity'),col('name','Customer'),col('orders','Orders','number'),col('delivered','Delivered','number'),money('delivered_value','Delivered item value'),col('first_order','First order in period','date'),col('last_order','Last order in period','date'),col('segment','Frequency')],
 metrics:[metric('customers','Identified contacts','COUNT(*)'),metric('repeat','Repeat in this period',`COUNT(*) FILTER(WHERE orders>=2)`),metric('value','Delivered item value','COALESCE(SUM(delivered_value),0)','money'),metric('orders','Orders with an identity','COALESCE(SUM(orders),0)')],
 sql:`WITH ${orderBase} SELECT customer_key,(ARRAY_AGG(COALESCE(customer_info #>> '{customerDetails,fullName}',customer_info #>> '{customerDetails,customerName}',customer_info->>'fullName',customer_info->>'customerName','Name not recorded') ORDER BY booked_at DESC NULLS LAST))[1] AS name,COUNT(*)::int AS orders,COUNT(*) FILTER(WHERE ${fulfilled})::int AS delivered,COALESCE(SUM(item_value) FILTER(WHERE ${fulfilled}),0) AS delivered_value,MIN(booked_at)::date::text AS first_order,MAX(booked_at)::date::text AS last_order,CASE WHEN COUNT(*)>=2 THEN 'Repeat in period' ELSE 'Single order in period' END AS segment FROM orders WHERE customer_key IS NOT NULL GROUP BY customer_key`,sort:'orders DESC,customer_key ASC'});
const walletBase = `${outlets}, wallet AS MATERIALIZED (
 SELECT w.*,r.outlet_name,r.station_code AS station FROM payments.vendor_wallet w LEFT JOIN outlets r USING(outlet_id)
 WHERE w.is_active IS TRUE AND ${scope('w.outlet_id','r.station_code')})`;
const walletNotes = ['Only active wallet transactions are included. Dates use the saved transaction_date, with the IST creation date only when transaction_date is missing.', 'Credit increases the wallet balance; debit reduces it. A wallet balance is not a bank reconciliation or proof of payout.'];
add({id:'wallet-ledger',title:'Wallet transaction ledger',group:'Finance',description:'Audit credits, debits, adjustments, deposits and recorded settlement margins.',basis:'Wallet transaction date',notes:walletNotes,dates:'period',scope:true,
 columns:[col('wallet_id','Transaction ID'),col('transaction_date','Transaction date','date'),col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('order_id','Order ID'),col('transaction_type','Type'),money('credit','Credit'),money('debit','Debit'),money('net','Net movement'),money('vendor_cut','Saved vendor cut'),money('margin','Saved margin'),col('description','Description')],
 metrics:[metric('transactions','Transactions','COUNT(*)'),metric('credit','Credits','COALESCE(SUM(credit),0)','money'),metric('debit','Debits','COALESCE(SUM(debit),0)','money'),metric('net','Net movement','COALESCE(SUM(net),0)','money')],
 sql:`WITH ${walletBase} SELECT wallet_id,COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)::text AS transaction_date,outlet_id,outlet_name,station,order_id,transaction_type,COALESCE(credit,0) AS credit,COALESCE(debit,0) AS debit,COALESCE(credit,0)-COALESCE(debit,0) AS net,vendor_cut,margin,description FROM wallet WHERE ${period("COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)")}`,sort:'transaction_date DESC,wallet_id DESC'});
add({id:'wallet-balances',title:'Outlet wallet balances & funding',group:'Finance',description:'Opening, movement, closing balance and funding-threshold exceptions.',basis:'Transaction-date period; closing balance through end date',notes:[...walletNotes,'Opening includes active entries before the start date. Closing includes all active entries through the end date (today if blank). When start is blank, opening is zero and movement includes all history. Missing thresholds are unconfigured.'],dates:'period',scope:true,
 columns:[col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),money('opening','Opening balance'),money('credit','Period credits'),money('debit','Period debits'),money('closing','Closing balance'),money('threshold','Funding threshold'),col('funding','Funding review')],
 metrics:[metric('outlets','Outlets','COUNT(*)'),metric('closing','Closing wallet total','COALESCE(SUM(closing),0)','money'),metric('negative','Negative balances','COUNT(*) FILTER(WHERE closing<0)'),metric('low','Below configured threshold','COUNT(*) FILTER(WHERE closing<threshold)')],
 sql:`WITH ${walletBase}, balances AS (
 SELECT outlet_id,COALESCE(SUM(COALESCE(credit,0)-COALESCE(debit,0)) FILTER(WHERE $1::date IS NOT NULL AND COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)<$1::date),0) AS opening,
 COALESCE(SUM(credit) FILTER(WHERE $1::date IS NULL OR COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)>=$1::date),0) AS credit,
 COALESCE(SUM(debit) FILTER(WHERE $1::date IS NULL OR COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)>=$1::date),0) AS debit,
 SUM(COALESCE(credit,0)-COALESCE(debit,0)) AS closing FROM wallet WHERE COALESCE(transaction_date,(created_at AT TIME ZONE 'Asia/Kolkata')::date)<=${asof} GROUP BY outlet_id), ids AS (SELECT outlet_id FROM outlets UNION SELECT outlet_id FROM balances)
 SELECT i.outlet_id,COALESCE(r.outlet_name,'Unmapped outlet') AS outlet_name,r.station_code AS station,COALESCE(b.opening,0) AS opening,COALESCE(b.credit,0) AS credit,COALESCE(b.debit,0) AS debit,COALESCE(b.closing,0) AS closing,r.wallet_threshold AS threshold,
 CASE WHEN COALESCE(b.closing,0)<0 THEN 'Negative balance' WHEN b.closing<r.wallet_threshold OR (b.closing IS NULL AND r.wallet_threshold>0) THEN 'Below threshold' WHEN r.wallet_threshold IS NULL THEN 'Threshold not configured' ELSE 'At or above threshold' END AS funding
 FROM ids i LEFT JOIN outlets r USING(outlet_id) LEFT JOIN balances b USING(outlet_id) WHERE ${scope('i.outlet_id','r.station_code')}`,sort:'closing ASC,outlet_id ASC'});
add({id:'vendor-settlements',title:'Vendor settlement performance',group:'Finance',description:'Recorded settlement activity grouped by vendor, with unmapped vendors visible.',basis:'Wallet transaction date; ORDER_SETTLEMENT entries only',notes:[...walletNotes,'Recorded settlement margin and vendor cut are ledger fields. They are not net profit and do not prove that money was transferred to a vendor. Multiple transactions for one order are not counted as multiple settled orders.'],dates:'period',scope:true,
 columns:[col('vendor_key','Vendor ID / mapping'),col('vendor_name','Vendor'),col('outlets','Outlets','number'),col('orders','Settled orders','number'),money('credit','Credit'),money('debit','Debit'),money('vendor_cut','Recorded vendor cut'),money('margin','Recorded settlement margin')],
 metrics:[metric('vendors','Vendor groups','COUNT(*)'),metric('orders','Settled orders','COALESCE(SUM(orders),0)'),metric('vendor_cut','Recorded vendor cut','COALESCE(SUM(vendor_cut),0)','money'),metric('margin','Recorded margin','COALESCE(SUM(margin),0)','money')],
 sql:`WITH ${walletBase} SELECT COALESCE(NULLIF(r.vendor_id,''),'Unmapped outlet '||w.outlet_id) AS vendor_key,COALESCE(v.vendor_name,'Vendor not mapped') AS vendor_name,COUNT(DISTINCT w.outlet_id)::int AS outlets,COUNT(DISTINCT NULLIF(w.order_id,''))::int AS orders,COALESCE(SUM(w.credit),0) AS credit,COALESCE(SUM(w.debit),0) AS debit,SUM(w.vendor_cut) AS vendor_cut,SUM(w.margin) AS margin FROM wallet w LEFT JOIN outlets r USING(outlet_id) LEFT JOIN restraunts.vendor_master v ON v.vendor_id::text=r.vendor_id WHERE w.transaction_type='ORDER_SETTLEMENT' AND ${period("COALESCE(w.transaction_date,(w.created_at AT TIME ZONE 'Asia/Kolkata')::date)")} GROUP BY COALESCE(NULLIF(r.vendor_id,''),'Unmapped outlet '||w.outlet_id),v.vendor_name`,sort:'orders DESC,vendor_key ASC',chart:{label:'vendor_name',value:'margin'}});
add({id:'invoices',title:'Invoice register & outstanding balances',group:'Finance',description:'Review signed invoices, paid amounts and outstanding balances without generating new invoices.',basis:'Invoices whose billing period overlaps the date range',notes:['Saved invoice amounts and statuses are reported unchanged. Positive outstanding and negative outstanding (credit balance) are shown separately; a negative invoice is not treated as unpaid revenue.', 'Age means days since invoice creation, not overdue days: the system has no invoice due-date field. Payment status does not independently verify bank receipt.'],dates:'period',scope:true,
 columns:[col('invoice_no','Invoice'),col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('period_start','Period start','date'),col('period_end','Period end','date'),money('invoice_amount','Signed invoice amount'),money('paid_amount','Saved paid amount'),money('outstanding_amount','Signed outstanding'),col('status','Saved status'),col('age_days','Days since creation','number')],
 metrics:[metric('invoices','Invoices','COUNT(*)'),metric('positive','Positive outstanding','COALESCE(SUM(outstanding_amount) FILTER(WHERE outstanding_amount>0),0)','money'),metric('credit','Outstanding credit balances','COALESCE(SUM(-outstanding_amount) FILTER(WHERE outstanding_amount<0),0)','money'),metric('paid','Saved paid amount','COALESCE(SUM(paid_amount),0)','money')],
 sql:`WITH ${outlets} SELECT i.invoice_no,i.outlet_id,r.outlet_name,r.station_code AS station,i.period_start::date::text AS period_start,i.period_end::date::text AS period_end,i.invoice_amount,i.paid_amount,i.outstanding_amount,i.status,GREATEST(0,(CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Kolkata')::date-i.created_at::date) AS age_days FROM payments.invoices i LEFT JOIN outlets r USING(outlet_id) WHERE ($1::date IS NULL OR i.period_end >= $1::date) AND ($2::date IS NULL OR i.period_start < $2::date+INTERVAL '1 day') AND ${scope('i.outlet_id','r.station_code')}`,sort:'period_end DESC,invoice_no ASC'});
add({id:'settlement-exceptions',title:'Order-to-wallet reconciliation exceptions',group:'Finance',description:'Find fulfilled orders without settlements and cancelled orders with wallet movement.',basis:'Order booking date (IST); all active settlement entries for each order',notes:[...orderNotes,'Matches active ORDER_SETTLEMENT entries by both outlet ID and trimmed order ID. A missing entry is a review exception, not proof of loss. Cancelled orders are flagged only when settlement credits or debits are nonzero.'],dates:'period',scope:true,
 columns:[col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),col('status','Order status'),money('item_value','Saved item value'),col('entries','Settlement entries','number'),money('credit','Credit'),money('debit','Debit'),money('margin','Recorded margin'),col('exception','Exception')],
 metrics:[metric('exceptions','Exceptions','COUNT(*)'),metric('missing','Missing settlements',`COUNT(*) FILTER(WHERE entries=0)`),metric('credit','Settlement credits on exceptions','COALESCE(SUM(credit),0)','money'),metric('debit','Settlement debits on exceptions','COALESCE(SUM(debit),0)','money')],
 sql:`WITH ${orderBase}, settled AS (SELECT TRIM(order_id) AS order_id,outlet_id,COUNT(*)::int AS entries,SUM(credit) AS credit,SUM(debit) AS debit,SUM(margin) AS margin FROM payments.vendor_wallet WHERE is_active IS TRUE AND transaction_type='ORDER_SETTLEMENT' GROUP BY TRIM(order_id),outlet_id)
 SELECT o.order_id,o.outlet_name,o.station,o.status,o.item_value,COALESCE(s.entries,0) AS entries,COALESCE(s.credit,0) AS credit,COALESCE(s.debit,0) AS debit,s.margin,CASE WHEN s.entries IS NULL THEN 'Fulfilled order without settlement' ELSE 'Cancelled order has settlement movement' END AS exception FROM orders o LEFT JOIN settled s ON s.order_id=o.order_id AND s.outlet_id=o.outlet_id WHERE ((o.status IN ('ORDER_DELIVERED','COMPLETED','ORDER_PARTIALLY_DELIVERED')) AND s.entries IS NULL) OR (o.status IN ('ORDER_CANCELLED','CANCELLED') AND (COALESCE(s.credit,0)<>0 OR COALESCE(s.debit,0)<>0))`,sort:'order_id DESC'});
add({id:'refunds',title:'Refund register',group:'Finance',description:'Track recorded refund amounts and their saved processing status.',basis:'Refund creation date (IST)',notes:['Refund status codes are shown as stored; the system does not provide a verified code-to-bank-outcome mapping. A saved refund does not prove payment-provider completion.'],dates:'period',scope:true,
 columns:[col('refund_id','Refund ID'),col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),money('amount','Refundable amount'),col('status','Saved status code'),col('created_at','Created','datetime')],metrics:[metric('refunds','Refund records','COUNT(*)'),metric('amount','Recorded refundable amount','COALESCE(SUM(amount),0)','money')],
 sql:`WITH ${outlets} SELECT f.refund_id,f.oid AS order_id,r.outlet_name,COALESCE(o.station_code,r.station_code) AS station,f.refundable_amount AS amount,f.status,to_char(f.created_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM-DD HH24:MI') AS created_at FROM payments.refunds f LEFT JOIN orders.orders_master o ON o.oid=f.oid LEFT JOIN outlets r ON r.outlet_id=o.outlet_id WHERE ${period("f.created_at AT TIME ZONE 'Asia/Kolkata'")} AND ${scope('o.outlet_id','COALESCE(o.station_code,r.station_code)')}`,sort:'created_at DESC,refund_id DESC'});
add({id:'complaints',title:'Complaints & resolution',group:'Quality',description:'Open cases, recorded closure times and customer-service workload.',basis:'Complaint creation date (IST)',notes:['Open = 0, in progress = 1, resolved = 2, matching the complaints workflow. Open-case age is measured now. Resolution hours require a saved closed_at timestamp; resolved cases without it remain unmeasured.', 'This report uses restraunts.complaints, the active complaints workflow, rather than the legacy orders.order_complaints table.'],dates:'period',scope:true,
 columns:[col('comp_id','Complaint ID'),col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),col('complaint','Complaint'),col('status','Status'),col('created_at','Opened','datetime'),col('closed_at','Closed','datetime'),col('age_hours','Open age (hours)','decimal'),col('resolution_hours','Resolution hours','decimal')],
 metrics:[metric('cases','Cases','COUNT(*)'),metric('open','Unresolved',`COUNT(*) FILTER(WHERE status<>'Resolved')`),metric('resolved','Resolved',`COUNT(*) FILTER(WHERE status='Resolved')`),metric('resolution','Avg recorded resolution hours','AVG(resolution_hours)','decimal')],
 sql:`WITH ${outlets} SELECT c.comp_id,c.order_id,r.outlet_name,COALESCE(o.station_code,r.station_code) AS station,c.complaint,CASE c.status WHEN 0 THEN 'Open' WHEN 1 THEN 'In progress' WHEN 2 THEN 'Resolved' ELSE 'Unknown ('||COALESCE(c.status::text,'null')||')' END AS status,to_char(c.created_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM-DD HH24:MI') AS created_at,to_char(c.closed_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM-DD HH24:MI') AS closed_at,CASE WHEN c.status<>2 THEN ROUND(EXTRACT(EPOCH FROM CURRENT_TIMESTAMP-c.created_at)/3600,1) END AS age_hours,CASE WHEN c.closed_at>=c.created_at THEN ROUND(EXTRACT(EPOCH FROM c.closed_at-c.created_at)/3600,1) END AS resolution_hours FROM restraunts.complaints c LEFT JOIN orders.orders_master o ON o.oid=c.order_id LEFT JOIN outlets r ON r.outlet_id=o.outlet_id WHERE ${period("c.created_at AT TIME ZONE 'Asia/Kolkata'")} AND ${scope('o.outlet_id','COALESCE(o.station_code,r.station_code)')}`,sort:'created_at DESC,comp_id DESC'});
add({id:'ratings',title:'Outlet ratings & feedback',group:'Quality',description:'Review recorded ratings and written customer feedback.',basis:'Review creation date (IST)',notes:['Only recorded ratings are averaged. No rating is inferred for an outlet without reviews.'],dates:'period',scope:true,
 columns:[col('rating_id','Rating ID'),col('order_id','Order ID'),col('outlet_name','Outlet'),col('station','Station'),col('rating','Rating','decimal'),col('review','Feedback'),col('created_at','Recorded','datetime')],metrics:[metric('reviews','Reviews','COUNT(*)'),metric('average','Average rating','AVG(rating)','decimal'),metric('low','Ratings 2 or lower','COUNT(*) FILTER(WHERE rating<=2)')],
 sql:`WITH ${outlets} SELECT v.rating_id,v.order_id,r.outlet_name,r.station_code AS station,v.rating,v.review,to_char(v.created_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM-DD HH24:MI') AS created_at FROM restraunts.reviews v LEFT JOIN outlets r ON r.outlet_id=v.res_id WHERE ${period("v.created_at AT TIME ZONE 'Asia/Kolkata'")} AND ${scope('v.res_id','r.station_code')}`,sort:'created_at DESC,rating_id DESC'});
add({id:'menu-margins',title:'Menu pricing & markup audit',group:'Network',description:'Find missing costs, below-cost prices and pending menu approvals.',basis:'Current menu snapshot',notes:['Markup is (base price − vendor price) ÷ vendor price × 100. It is not gross margin percentage on sales. Current menu prices are not historical order costs.', 'The report shows saved prices and approval/sync flags without pushing changes to IRCTC.'],dates:'none',scope:true,
 columns:[col('item_id','Item ID'),col('item_name','Item'),col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),money('vendor_price','Vendor price'),money('base_price','Base price'),money('spread','Base minus cost'),col('markup_pct','Markup %','percent'),col('review','Pricing review'),col('approval','Approval'),col('sync','Saved sync flag')],
 metrics:[metric('items','Items','COUNT(*)'),metric('missing','Missing / nonpositive cost',`COUNT(*) FILTER(WHERE vendor_price IS NULL OR vendor_price<=0)`),metric('below','Below vendor cost','COUNT(*) FILTER(WHERE base_price<vendor_price)'),metric('pending','Not approved',`COUNT(*) FILTER(WHERE approval<>'Approved')`)],
 sql:`WITH ${outlets} SELECT d.item_id,d.item_name,d.outlet_id,r.outlet_name,r.station_code AS station,d.vendor_price,d.base_price,d.base_price-d.vendor_price AS spread,CASE WHEN d.vendor_price>0 THEN ROUND(((d.base_price::numeric-d.vendor_price)/d.vendor_price)*100,2) END AS markup_pct,CASE WHEN d.vendor_price IS NULL OR d.vendor_price<=0 THEN 'Vendor cost missing / nonpositive' WHEN d.base_price<d.vendor_price THEN 'Below vendor cost' ELSE 'At or above vendor cost' END AS review,CASE WHEN d.verified IS TRUE THEN 'Approved' ELSE 'Not approved' END AS approval,CASE WHEN d.irctc_synced THEN 'Saved as synced' ELSE 'Not marked synced' END AS sync FROM restraunts.dish_master d LEFT JOIN outlets r USING(outlet_id) WHERE ${scope('d.outlet_id','r.station_code')}`,sort:'markup_pct ASC NULLS FIRST,item_id ASC'});
add({id:'compliance',title:'Outlet compliance & FSSAI expiry',group:'Network',description:'Prioritize expired, expiring, missing and unparseable license records.',basis:'Current outlet details, license expiry evaluated as of selected date',notes:['Expiry uses the system’s existing safe date parser. An unparseable date is flagged for review instead of being treated as valid.', 'These are saved license details, not independent verification with an authority. Outlet status codes are shown as stored because existing modules disagree on some labels.'],dates:'asof',scope:true,
 columns:[col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('status','Saved outlet status'),col('fssai','Saved FSSAI number'),col('raw_expiry','Saved expiry text'),col('expiry','Parsed expiry','date'),col('days_left','Days to expiry','number'),col('compliance','Review status'),col('email','Email'),col('phone','Phone')],
 metrics:[metric('outlets','Outlets','COUNT(*)'),metric('expired','Expired',`COUNT(*) FILTER(WHERE compliance='Expired')`),metric('soon','Expires within 30 days',`COUNT(*) FILTER(WHERE compliance='Expires within 30 days')`),metric('review','Missing / invalid records',`COUNT(*) FILTER(WHERE compliance IN ('License missing','Expiry missing','Unparseable expiry'))`)],
 sql:`WITH ${outlets} SELECT outlet_id,outlet_name,station_code AS station,status,fssai::text AS fssai,fssai_valid AS raw_expiry,public.safe_parse_created_at(fssai_valid)::date::text AS expiry,public.safe_parse_created_at(fssai_valid)::date-${asof} AS days_left,CASE WHEN fssai IS NULL OR fssai<=0 THEN 'License missing' WHEN NULLIF(TRIM(fssai_valid),'') IS NULL THEN 'Expiry missing' WHEN public.safe_parse_created_at(fssai_valid) IS NULL THEN 'Unparseable expiry' WHEN public.safe_parse_created_at(fssai_valid)::date<${asof} THEN 'Expired' WHEN public.safe_parse_created_at(fssai_valid)::date<=${asof}+30 THEN 'Expires within 30 days' ELSE 'Expiry later than 30 days' END AS compliance,email,phone::text AS phone FROM outlets WHERE ${scope('outlet_id','station_code')}`,sort:'days_left ASC NULLS FIRST,outlet_id ASC'});
const peopleNotes = ['People reports are read-only and exclude passwords, bank details, tokens and private documents.'];
add({id:'network-health',title:'Outlet activation & demand gaps',group:'Network',description:'Find active outlets without orders, active menu items or station mappings.',basis:'Current outlet/menu snapshot with orders in the booking-date period',notes:[...orderNotes,'Every mapped outlet is included, even with no orders in the selected period. Outlet status 1 is active; other codes are shown unchanged. Duplicate outlet master rows are reduced to one business outlet, preferring an active record.'],dates:'period',scope:true,
 columns:[col('outlet_id','Outlet ID'),col('outlet_name','Outlet'),col('station','Station'),col('status','Saved outlet status'),col('orders','Period orders','number'),col('active_dishes','Active menu items','number'),col('period_last_order','Last order in period','date'),money('delivered_value','Delivered item value'),col('review','Action to review')],
 metrics:[metric('outlets','Mapped outlets','COUNT(*)'),metric('active','Active outlets','COUNT(*) FILTER(WHERE status=1)'),metric('silent','Active without period orders','COUNT(*) FILTER(WHERE status=1 AND orders=0)'),metric('no_menu','Active without active menu','COUNT(*) FILTER(WHERE status=1 AND active_dishes=0)')],
 sql:`WITH ${orderBase}, activity AS (SELECT outlet_id,COUNT(*)::int AS orders,MAX(booked_at)::date::text AS last_order,COALESCE(SUM(item_value) FILTER(WHERE ${fulfilled}),0) AS delivered_value FROM orders GROUP BY outlet_id), menu AS (SELECT outlet_id,COUNT(*) FILTER(WHERE status=1)::int AS active_dishes FROM restraunts.dish_master GROUP BY outlet_id)
 SELECT r.outlet_id,r.outlet_name,r.station_code AS station,r.status,COALESCE(a.orders,0) AS orders,COALESCE(m.active_dishes,0) AS active_dishes,a.last_order AS period_last_order,COALESCE(a.delivered_value,0) AS delivered_value,CASE WHEN NULLIF(TRIM(r.station_code),'') IS NULL THEN 'Station mapping missing' WHEN r.status=1 AND COALESCE(m.active_dishes,0)=0 THEN 'Active without active menu' WHEN r.status=1 AND a.orders IS NULL THEN 'Active without period orders' WHEN r.status=1 THEN 'Active with period orders' ELSE 'Review saved outlet status' END AS review FROM outlets r LEFT JOIN activity a USING(outlet_id) LEFT JOIN menu m USING(outlet_id) WHERE ${scope('r.outlet_id','r.station_code')}`,sort:'orders ASC,outlet_id ASC'});
add({id:'employees',title:'Workforce directory',group:'People',description:'Review active staffing, departments, roles and joining dates.',basis:'Current employee snapshot',notes:peopleNotes,dates:'none',scope:false,
 columns:[col('emp_id','Employee ID'),col('name','Employee'),col('department','Department'),col('role','Role'),col('status','Saved status'),col('joined','Joining date','date'),col('work_shift','Shift'),col('job_location','Location')],metrics:[metric('employees','Employees','COUNT(*)'),metric('active','Active',`COUNT(*) FILTER(WHERE status='Active')`),metric('departments','Departments','COUNT(DISTINCT department)')],
 sql:`SELECT e.emp_id,e.name,d.name AS department,r.name AS role,CASE WHEN e.is_active IS TRUE THEN 'Active' WHEN e.is_active IS FALSE THEN 'Inactive' ELSE 'Unrecorded' END AS status,(e.date_of_joining AT TIME ZONE 'Asia/Kolkata')::date::text AS joined,e.work_shift,e.job_location FROM hr.employees e LEFT JOIN hr.roles r USING(role_id) LEFT JOIN hr.departments d ON d.dept_id=r.dept_id`,sort:'name ASC,emp_id ASC'});
add({id:'attendance',title:'Attendance & recorded hours',group:'People',description:'Review recorded check-ins, check-outs and incomplete punches.',basis:'Attendance record creation date (IST)',notes:[...peopleNotes,'Worked hours are measured only where check-out is not earlier than check-in. Overnight shifts cannot be inferred from time-only fields. Missing punches are flagged; absence is not inferred without a shift calendar.'],dates:'period',scope:false,
 columns:[col('att_id','Record ID'),col('name','Employee'),col('day','Day','date'),col('check_in','Check-in'),col('check_out','Check-out'),col('hours','Recorded hours','decimal'),col('review','Punch review')],metrics:[metric('punches','Attendance records','COUNT(*)'),metric('employees','Employees with records','COUNT(DISTINCT emp_id)'),metric('incomplete','Records to review',`COUNT(*) FILTER(WHERE review<>'Complete')`),metric('hours','Measured hours','SUM(hours)','decimal')],
 sql:`SELECT a.att_id,a.emp_id,e.name,(a.created_at AT TIME ZONE 'Asia/Kolkata')::date::text AS day,a.check_in::text,a.check_out::text,CASE WHEN check_out>=check_in THEN ROUND(EXTRACT(EPOCH FROM check_out-check_in)/3600,2) END AS hours,CASE WHEN check_in IS NULL THEN 'Missing check-in' WHEN check_out IS NULL THEN 'Missing check-out' WHEN check_out<check_in THEN 'Overnight / invalid times: review' ELSE 'Complete' END AS review FROM hr.attendence a LEFT JOIN hr.employees e USING(emp_id) WHERE ${period("a.created_at AT TIME ZONE 'Asia/Kolkata'")}`,sort:'day DESC,att_id DESC'});
add({id:'leave-balances',title:'Employee leave balances',group:'People',description:'Current casual, earned, sick and short-leave balances.',basis:'Current leave balance snapshot',notes:[...peopleNotes,'The system stores balances, not a dated leave-request ledger. Leave taken during a historical period cannot be reconstructed from these balances.'],dates:'none',scope:false,
 columns:[col('emp_id','Employee ID'),col('name','Employee'),col('casual_leave','Casual','number'),col('earned_leave','Earned','number'),col('sick_leave','Sick','number'),col('short_leave','Short','number')],metrics:[metric('employees','Employees with balances','COUNT(*)'),metric('casual','Casual balance','SUM(casual_leave)'),metric('earned','Earned balance','SUM(earned_leave)'),metric('sick','Sick balance','SUM(sick_leave)')],
 sql:`SELECT l.emp_id,e.name,l.casual_leave,l.earned_leave,l.sick_leave,l.short_leave FROM hr.leaves l LEFT JOIN hr.employees e USING(emp_id)`,sort:'name ASC,emp_id ASC'});
add({id:'payroll',title:'Payroll & payslip register',group:'People',description:'Saved gross earnings, deductions, net salary and batch status.',basis:'Payslip creation date (IST); salary month shown separately',notes:[...peopleNotes,'Batch status is the application’s saved status. It is not independent confirmation of a bank transfer. Salary totals are taken from saved payslips, not recalculated from current employee salary.'],dates:'period',scope:false,
 columns:[col('payslip_id','Payslip ID'),col('month_year','Salary month'),col('name','Employee'),col('batch_id','Batch ID'),col('batch_status','Saved batch status'),col('payable_days','Payable days','decimal'),money('gross_earnings','Gross earnings'),money('total_deductions','Deductions'),money('net_salary','Net salary'),col('created_at','Created','datetime')],metrics:[metric('payslips','Payslips','COUNT(*)'),metric('gross','Saved gross earnings','COALESCE(SUM(gross_earnings),0)','money'),metric('deductions','Saved deductions','COALESCE(SUM(total_deductions),0)','money'),metric('net','Saved net salary','COALESCE(SUM(net_salary),0)','money')],
 sql:`SELECT p.payslip_id,p.month_year,e.name,p.batch_id,b.status AS batch_status,p.payable_days,p.gross_earnings,p.total_deductions,p.net_salary,to_char(p.created_at AT TIME ZONE 'Asia/Kolkata','YYYY-MM-DD HH24:MI') AS created_at FROM hr.payslips p LEFT JOIN hr.employees e USING(emp_id) LEFT JOIN hr.payroll_batches b USING(batch_id) WHERE ${period("p.created_at AT TIME ZONE 'Asia/Kolkata'")}`,sort:'created_at DESC,payslip_id DESC'});
add({id:'recruitment',title:'Recruitment pipeline',group:'People',description:'Hiring demand, candidate stages and saved offer counts by job.',basis:'Job creation date (IST); candidates and offers are current counts for those jobs',notes:[...peopleNotes,'Headcount is the job’s configured requirement. Candidate and offer counts are not automatically treated as hires.'],dates:'period',scope:false,
 columns:[col('job_id','Job ID'),col('title','Job'),col('department','Department'),col('station','Station'),col('status','Saved status'),col('headcount','Required headcount','number'),col('candidates','Candidates','number'),col('offers','Offers','number'),col('accepted','Saved accepted offers','number'),col('stages','Candidate stages')],metrics:[metric('jobs','Jobs','COUNT(*)'),metric('headcount','Configured headcount','COALESCE(SUM(headcount),0)'),metric('candidates','Candidates','COALESCE(SUM(candidates),0)'),metric('offers','Offers','COALESCE(SUM(offers),0)')],
 sql:`SELECT j.job_id,j.title,d.name AS department,j.station_code AS station,j.status,j.headcount,(SELECT COUNT(*)::int FROM hr.candidates c WHERE c.job_id=j.job_id) AS candidates,(SELECT COUNT(*)::int FROM hr.offer_letters f JOIN hr.candidates c USING(candidate_id) WHERE c.job_id=j.job_id) AS offers,(SELECT COUNT(*)::int FROM hr.offer_letters f JOIN hr.candidates c USING(candidate_id) WHERE c.job_id=j.job_id AND f.accepted_at IS NOT NULL) AS accepted,(SELECT STRING_AGG(stage||': '||cnt,', ' ORDER BY stage) FROM (SELECT COALESCE(stage,'Unrecorded') AS stage,COUNT(*) AS cnt FROM hr.candidates c WHERE c.job_id=j.job_id GROUP BY stage) x) AS stages FROM hr.job_openings j LEFT JOIN hr.departments d USING(dept_id) WHERE ${period("j.created_at AT TIME ZONE 'Asia/Kolkata'")}`,sort:'job_id DESC'});

export class ReportInputError extends Error {statusCode=400;}
export class ReportsModel {
    catalog() {return specs.map(({sql,metrics,sort,...s})=>({...s,metrics:metrics.map(({sql,...m})=>m),default_sort:sort.split(' ')[0]}));}
    async metadata() {
        const client=await usersDBPool.connect();
        try {
            await client.query('BEGIN ISOLATION LEVEL REPEATABLE READ READ ONLY');
            const [coverage,locations] = await Promise.all([
                client.query(`SELECT COUNT(*)::int AS order_count,MIN(public.safe_parse_created_at(created_at))::date::text AS first_order,MAX(public.safe_parse_created_at(created_at))::date::text AS last_order,COUNT(*) FILTER(WHERE public.safe_parse_created_at(created_at) IS NULL)::int AS invalid_order_dates FROM orders.orders_master`),
                client.query(`WITH ${outlets} SELECT outlet_id,outlet_name,station_code FROM outlets ORDER BY outlet_name NULLS LAST,outlet_id`)
            ]);
            await client.query('COMMIT');
            return {reports:this.catalog(),coverage:coverage.rows[0],outlets:locations.rows,timezone:'Asia/Kolkata',currency:'INR'};
        } catch(error){await client.query('ROLLBACK');throw error;} finally{client.release();}
    }
    async fetch(id: string, params: any, all=false) {
        const spec=specs.find(s=>s.id===id);if(!spec) throw new ReportInputError('Unknown report.');
        const date=(value:any)=>{
            if(value==null||value==='')return null;
            if(typeof value!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(value)||!Number.isFinite(Date.parse(value+'T00:00:00Z'))||new Date(value+'T00:00:00Z').toISOString().slice(0,10)!==value)throw new ReportInputError('Use valid dates in YYYY-MM-DD format.');
            return value;
        };
        const from=date(params.from),to=date(params.to);
        if(from&&to&&from>to)throw new ReportInputError('Start date must be on or before end date.');
        if(spec.dates==='none'&&(from||to)||spec.dates==='asof'&&from)throw new ReportInputError('This snapshot report does not support a historical start date.');
        const outlet=params.outlet_id==null||params.outlet_id===''?null:Number(params.outlet_id);
        if(outlet!==null&&(!Number.isInteger(outlet)||outlet<1||outlet>2147483647))throw new ReportInputError('Use a valid outlet ID.');
        if(typeof params.station==='object'||typeof params.search==='object')throw new ReportInputError('Filters must contain a single value.');
        const station=String(params.station||'').trim()||null,search=String(params.search||'').trim();
        if((station?.length||0)>30||search.length>200)throw new ReportInputError('Filter text is too long.');
        if(!spec.scope&&(outlet||station))throw new ReportInputError('Outlet and station filters are not applicable to this people report.');
        const page=params.page==null?0:Number(params.page),limit=params.limit==null?25:Number(params.limit);
        if(!Number.isInteger(page)||page<0||page>1000000||!Number.isInteger(limit)||limit<1||limit>100)throw new ReportInputError('Use a page of 0 or above and a page size between 1 and 100.');
        const sort=params.sort?String(params.sort):null,direction=params.direction?String(params.direction).toUpperCase():'ASC';
        if(sort&&!spec.columns.some(c=>c.key===sort)||!['ASC','DESC'].includes(direction))throw new ReportInputError('Choose a valid sort column and direction.');
        const ordering=sort?`"${sort}" ${direction} NULLS LAST,${spec.sort}`:spec.sort;
        const columns=spec.columns.map(c=>`"${c.key}"`).join(',');
        const searchSql=spec.columns.map(c=>`src."${c.key}"::text`).join(',');
        const metricsSql=spec.metrics.map(m=>`'${m.key}',(${m.sql})`).join(',');
        const chart=spec.chart?.kind==='trend'?`COALESCE((SELECT json_agg(c) FROM (SELECT label,value FROM (SELECT "${spec.chart.label}" AS label,"${spec.chart.value}" AS value FROM filtered WHERE "${spec.chart.label}" IS NOT NULL ORDER BY "${spec.chart.label}" DESC LIMIT 30) recent ORDER BY label ASC) c),'[]'::json)`:
          spec.chart?`COALESCE((SELECT json_agg(c) FROM (SELECT "${spec.chart.label}" AS label,"${spec.chart.value}" AS value FROM filtered WHERE "${spec.chart.value}" IS NOT NULL ORDER BY "${spec.chart.value}" DESC NULLS LAST,"${spec.chart.label}" ASC LIMIT 10) c),'[]'::json)`:`'[]'::json`;
        // Include typed filter parameters even for snapshots without date/scoping clauses.
        const sql=`WITH parameters AS (SELECT $1::date,$2::date,$3::int,$4::text), source AS MATERIALIZED (${spec.sql}),
          filtered AS MATERIALIZED (SELECT * FROM source src WHERE $5::text='' OR CONCAT_WS(' ',${searchSql}) ILIKE '%'||$5||'%')
          SELECT json_build_object('rows',COALESCE((SELECT json_agg(p) FROM (SELECT ${columns} FROM filtered ORDER BY ${ordering} LIMIT $6 OFFSET $7) p),'[]'::json),
          'total',(SELECT COUNT(*)::int FROM filtered),'summary',(SELECT json_build_object(${metricsSql}) FROM filtered),'chart',${chart}) AS report`;
        const client=await usersDBPool.connect();
        try {
            await client.query('BEGIN READ ONLY');
            await client.query(`SET LOCAL statement_timeout = '20000'`);
            const r=await client.query(sql,[from,to,outlet,station,search,all?100001:limit,all?0:page*limit]);
            if(all&&r.rows[0].report.total>100000)throw new ReportInputError('This export exceeds 100,000 rows. Narrow the date range or filters.');
            await client.query('COMMIT');
            return {...r.rows[0].report,report:this.catalog().find(s=>s.id===id),filters:{from,to,outlet_id:outlet,station,search,sort,direction},page,limit,generated_at:new Date().toISOString(),timezone:'Asia/Kolkata',currency:'INR'};
        } catch(error){await client.query('ROLLBACK');throw error;} finally{client.release();}
    }
}
